 7	func matchScheme(domain, pattern string) bool {
 8		didx := strings.Index(domain, ":")
 9		pidx := strings.Index(pattern, ":")
10		return didx != -1 && pidx != -1 && domain[:didx] == pattern[:pidx]
11	}
