13	// matchSubdomain compares authority with wildcard
14	func matchSubdomain(domain, pattern string) bool {
15		if !matchScheme(domain, pattern) {
16			return false
17		}
18		didx := strings.Index(domain, "://")
19		pidx := strings.Index(pattern, "://")
20		if didx == -1 || pidx == -1 {
21			return false
22		}
23		domAuth := domain[didx+3:]
24		// to avoid long loop by invalid long domain
25		if len(domAuth) > 253 {
26			return false
27		}
28		patAuth := pattern[pidx+3:]
29	
30		domComp := strings.Split(domAuth, ".")
31		patComp := strings.Split(patAuth, ".")
32		for i := len(domComp)/2 - 1; i >= 0; i-- {
33			opp := len(domComp) - 1 - i
34			domComp[i], domComp[opp] = domComp[opp], domComp[i]
35		}
36		for i := len(patComp)/2 - 1; i >= 0; i-- {
37			opp := len(patComp) - 1 - i
38			patComp[i], patComp[opp] = patComp[opp], patComp[i]
39		}
40	
41		for i, v := range domComp {
42			if len(patComp) <= i {
43				return false
44			}
45			p := patComp[i]
46			if p == "*" {
47				return true
48			}
49			if p != v {
50				return false
51			}
52		}
53		return false
54	}

