   352	func (e *Echo) DefaultHTTPErrorHandler(err error, c Context) {
   353		he, ok := err.(*HTTPError)
   354		if ok {
   355			if he.Internal != nil {
   356				if herr, ok := he.Internal.(*HTTPError); ok {
   357					he = herr
   358				}
   359			}
   360		} else {
   361			he = &HTTPError{
   362				Code:    http.StatusInternalServerError,
   363				Message: http.StatusText(http.StatusInternalServerError),
   364			}
   365		}
   366	
   367		// Issue #1426
   368		code := he.Code
   369		message := he.Message
   370		if m, ok := he.Message.(string); ok {
   371			if e.Debug {
   372				message = Map{"message": m, "error": err.Error()}
   373			} else {
   374				message = Map{"message": m}
   375			}
   376		}
   377	
   378		// Send response
   379		if !c.Response().Committed {
   380			if c.Request().Method == http.MethodHead { // Issue #608
   381				err = c.NoContent(he.Code)
   382			} else {
   383				err = c.JSON(code, message)
   384			}
   385			if err != nil {
   386				e.Logger.Error(err)
   387			}
   388		}
