var routePool = []string{
	"/", "/a", "/ab", "/:id", "/*", "/a/:id", "/a/*", "/a/b", "/a/b/c",
	"/:id/b", "/:id/:id2", "/users/:id/edit", "/users/create",
	"/users/:id/active", "/a/:id/*",
}

var pathPool = []string{
	"/", "/a", "/ab", "/abc", "/a/", "/a/b", "/a/b/c", "/a/b/c/d",
	"/users/create", "/users/createNotFound", "/users/alice/edit",
	"/x", "/x/y", "/x/y/z", "", "//", "/a//b", "/users", "/users/",
	"/users/alice", "/users/alice/active", "/a/b/c/d/e", "/a/x/y",
	"/ab/c", "/abc/d",
}

func segs(p string) []string {
	if p == "" || p == "/" {
		return nil
	}
	p = strings.TrimPrefix(p, "/")
	return strings.Split(p, "/")
}

// naive matcher, param matches any single segment (including empty)
func naiveMatch(pattern, path string) bool {
	if pattern == "" {
		pattern = "/"
	}
	if !strings.HasPrefix(pattern, "/") {
		pattern = "/" + pattern
	}
	if path == "" {
		path = "/"
	}
	if !strings.HasPrefix(path, "/") {
		path = "/" + path
	}
	ps, xs := segs(pattern), segs(path)
	for len(ps) > 0 {
		if ps[0] == "*" {
			return true
		}
		if len(xs) == 0 {
			return false
		}
		if strings.HasPrefix(ps[0], ":") {
			ps, xs = ps[1:], xs[1:]
			continue
		}
		if ps[0] != xs[0] {
			return false
		}
		ps, xs = ps[1:], xs[1:]
	}
	return len(xs) == 0
}

func run(routes []string, path string) (panicked interface{}, ctxHandlerNil bool, isNF, isMNA bool) {
	defer func() {
		if r := recover(); r != nil {
			panicked = r
		}
	}()
	e := echo.New()
	for _, rt := range routes {
		e.Add(http.MethodGet, rt, func(c echo.Context) error { return nil })
	}
	c := e.NewContext(nil, nil)
	e.Router().Find(http.MethodGet, path, c)
	h := c.Handler()
	if h == nil {
		ctxHandlerNil = true
		return
	}
	isNF = fmt.Sprintf("%p", h) == fmt.Sprintf("%p", echo.NotFoundHandler)
	isMNA = fmt.Sprintf("%p", h) == fmt.Sprintf("%p", echo.MethodNotAllowedHandler)
	return
}

func check(t *testing.T, routes []string, path string, fails *int) {
	p, nilH, isNF, isMNA := run(routes, path)
	if p != nil {
		*fails++
		if *fails < 40 {
			t.Errorf("PANIC routes=%v path=%q err=%v", routes, path, p)
		}
		return
	}
	if nilH {
		*fails++
		if *fails < 40 {
			t.Errorf("NIL HANDLER routes=%v path=%q", routes, path)
		}
		return
	}
	matches := false
	for _, rt := range routes {
		if naiveMatch(rt, path) {
			matches = true
			break
		}
	}
	if !matches && !isNF {
		*fails++
		if *fails < 40 {
			t.Errorf("EXPECTED NotFound routes=%v path=%q gotMNA=%v", routes, path, isMNA)
		}
	}
}

