package routerfuzz

import (
	"fmt"
	"math/rand"
	"net/http"
	"strings"
	"testing"

	"github.com/labstack/echo/v4"
)

var statics = []string{"a", "b", "c", "ab", "abc", "users", "create", "edit", "alice", "x"}

func randPattern(rnd *rand.Rand) string {
	nseg := 1 + rnd.Intn(4)
	segs := make([]string, 0, nseg)
	for i := 0; i < nseg; i++ {
		switch r := rnd.Intn(10); {
		case r < 6:
			segs = append(segs, statics[rnd.Intn(len(statics))])
		case r < 9:
			segs = append(segs, ":"+[]string{"id", "id2", "name"}[rnd.Intn(3)])
		default:
			if i == nseg-1 {
				segs = append(segs, "*")
			} else {
				segs = append(segs, statics[rnd.Intn(len(statics))])
			}
		}
	}
	p := "/" + strings.Join(segs, "/")
	if rnd.Intn(6) == 0 {
		p += "/"
	}
	return p
}

func randPath(rnd *rand.Rand) string {
	nseg := rnd.Intn(5)
	segs := make([]string, 0, nseg)
	for i := 0; i < nseg; i++ {
		if rnd.Intn(8) == 0 {
			segs = append(segs, "")
			continue
		}
		segs = append(segs, statics[rnd.Intn(len(statics))])
	}
	p := "/" + strings.Join(segs, "/")
	if rnd.Intn(4) == 0 {
		p += "/"
	}
	return p
}

type routeDef struct {
	pattern string
	method  string
}

func oracleMatch(pattern, path string) bool {
	if pattern == "" {
		pattern = "/"
	}
	if !strings.HasPrefix(pattern, "/") {
		pattern = "/" + pattern
	}
	if path == "" {
		path = "/"
	}
	if !strings.HasPrefix(path, "/") {
		path = "/" + path
	}
	ps, xs := segs(pattern), segs(path)
	for len(ps) > 0 {
		if ps[0] == "*" {
			return true
		}
		if len(xs) == 0 {
			return false
		}
		if strings.HasPrefix(ps[0], ":") {
			ps, xs = ps[1:], xs[1:]
			continue
		}
		if ps[0] != xs[0] {
			return false
		}
		ps, xs = ps[1:], xs[1:]
	}
	return len(xs) == 0
}

func run2(routes []routeDef, method, path string) (panicked interface{}, h echo.HandlerFunc) {
	defer func() {
		if r := recover(); r != nil {
			panicked = r
		}
	}()
	e := echo.New()
	for _, rd := range routes {
		e.Add(rd.method, rd.pattern, func(c echo.Context) error { return nil })
	}
	c := e.NewContext(nil, nil)
	e.Router().Find(method, path, c)
	return nil, c.Handler()
}

func TestFuzzRandom(t *testing.T) {
	rnd := rand.New(rand.NewSource(1234))
	fails := 0
	nfp := fmt.Sprintf("%p", echo.NotFoundHandler)
	mnap := fmt.Sprintf("%p", echo.MethodNotAllowedHandler)
	for iter := 0; iter < 30000; iter++ {
		nroutes := 1 + rnd.Intn(6)
		var routes []routeDef
		for i := 0; i < nroutes; i++ {
			m := http.MethodGet
			if rnd.Intn(3) == 0 {
				m = http.MethodPost
			}
			routes = append(routes, routeDef{randPattern(rnd), m})
		}
		npaths := 1 + rnd.Intn(4)
		for j := 0; j < npaths; j++ {
			path := randPath(rnd)
			method := http.MethodGet
			if rnd.Intn(3) == 0 {
				method = http.MethodPost
			}
			p, h := run2(routes, method, path)
			if p != nil {
				fails++
				if fails < 20 {
					t.Errorf("PANIC routes=%v method=%s path=%q err=%v", routes, method, path, p)
				}
				continue
			}
			hp := fmt.Sprintf("%p", h)
			if h == nil {
				fails++
				if fails < 20 {
					t.Errorf("NIL HANDLER routes=%v method=%s path=%q", routes, method, path)
				}
				continue
			}
			sameMethod, otherMethod := false, false
			for _, rd := range routes {
				if oracleMatch(rd.pattern, path) {
					if rd.method == method {
						sameMethod = true
					} else {
						otherMethod = true
					}
				}
			}
			switch {
			case sameMethod:
				if hp == nfp || hp == mnap {
					fails++
					if fails < 20 {
						t.Errorf("MISSED MATCH routes=%v method=%s path=%q gotNF=%v gotMNA=%v", routes, method, path, hp == nfp, hp == mnap)
					}
				}
			case otherMethod:
				if hp != mnap {
					fails++
					if fails < 20 {
						t.Errorf("EXPECT MNA routes=%v method=%s path=%q gotNF=%v", routes, method, path, hp == nfp)
					}
				}
			default:
				if hp != nfp {
					fails++
					if fails < 20 {
						t.Errorf("EXPECT NF routes=%v method=%s path=%q gotMNA=%v", routes, method, path, hp == mnap)
					}
				}
			}
		}
	}
	fmt.Println("random fuzz failures:", fails)
}
